import XCTest
@testable import Remo

/// Runs the shared corrections fixture through this platform's timeline
/// algorithm and compares it with the result the web implementation produced
/// (fixtures/timeline/corrections.expected.json, regenerated by
/// apps/web/src/corrections-golden.test.ts).
final class CorrectionsFixtureTests: XCTestCase {
    private func fixture(_ name: String) throws -> Data {
        let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("../../../../fixtures/timeline").standardized
        return try Data(contentsOf: root.appendingPathComponent(name))
    }

    private struct Expected: Decodable {
        struct Activity: Decodable {
            let kind: String
            let startedAt: Int64
            let endedAt: Int64
            let latitude: Double?
            let longitude: Double?
            let placeId: String?
            let corrected: Bool?
            let untrackedMs: Int64?
            let photoCount: Int
        }
        struct Outlier: Decodable {
            let startedAt: Int64
            let endedAt: Int64
            let eventIds: [String]
        }
        struct Case: Decodable {
            let name: String
            let activities: [Activity]
            let outliers: [Outlier]
        }
        struct AllPlace: Decodable {
            let placeId: String?
            let latitude: Double
            let longitude: Double
            let visitCount: Int
            let dayCount: Int
            let totalDurationMs: Int64
        }
        let cases: [Case]
        let allPlaces: [AllPlace]
    }

    private let order = Date(timeIntervalSince1970: 0)

    private func events(_ day: String, extra: [[String: Any]] = []) throws -> [LogEntry] {
        let sample = try TimelineImport.decode(data: fixture("remo-timeline-\(day).sample.json"), importedAt: order)
        let added = extra.compactMap { TimelineImport.decodeEvent($0, importedAt: order) }
        return (sample + added).sorted { $0.startedAt < $1.startedAt }
    }

    private func milliseconds(_ date: Date) -> Int64 { Int64((date.timeIntervalSince1970 * 1000).rounded()) }

    private func number(_ value: Any?) -> Double? { (value as? NSNumber)?.doubleValue }

    private func correction(_ raw: [String: Any]) -> TimelineCorrection? {
        guard let id = raw["id"] as? String,
              let kind = (raw["kind"] as? String).flatMap(TimelineCorrectionKind.init(rawValue:)),
              let startedAt = number(raw["startedAt"]),
              let endedAt = number(raw["endedAt"]),
              let createdAt = number(raw["createdAt"]) else { return nil }
        return TimelineCorrection(
            id: id,
            kind: kind,
            startedAt: Date(timeIntervalSince1970: startedAt / 1000),
            endedAt: Date(timeIntervalSince1970: endedAt / 1000),
            createdAt: Int64(createdAt.rounded()),
            source: TimelineCorrectionSource(rawValue: raw["source"] as? String ?? "") ?? .app,
            deleted: raw["deleted"] as? Bool ?? false,
        )
    }

    private func places(_ raw: [[String: Any]]) -> [NamedPlace] {
        raw.compactMap { place in
            guard let id = place["id"] as? String, let latitude = number(place["latitude"]), let longitude = number(place["longitude"]) else { return nil }
            let anchors = (place["anchors"] as? [[String: Any]] ?? []).compactMap { anchor -> PlaceAnchor? in
                guard let latitude = number(anchor["latitude"]), let longitude = number(anchor["longitude"]), let radius = number(anchor["radiusMeters"]) else { return nil }
                return PlaceAnchor(latitude: latitude, longitude: longitude, radiusMeters: radius)
            }
            return NamedPlace(
                id: id,
                name: place["name"] as? String ?? "",
                latitude: latitude,
                longitude: longitude,
                radiusMeters: number(place["radiusMeters"]),
                anchors: anchors,
                mergedInto: place["mergedInto"] as? String,
                updatedAt: order,
                deleted: place["deleted"] as? Bool ?? false,
            )
        }
    }

    func testProducesTheCorrectedTimelinesEveryPlatformExpects() throws {
        let root = try XCTUnwrap(JSONSerialization.jsonObject(with: fixture("corrections.cases.json")) as? [String: Any])
        let rawCases = try XCTUnwrap(root["cases"] as? [[String: Any]])
        let expected = try JSONDecoder().decode(Expected.self, from: fixture("corrections.expected.json"))
        XCTAssertEqual(rawCases.map { $0["name"] as? String }, expected.cases.map(\.name))

        for (raw, item) in zip(rawCases, expected.cases) {
            let day = try XCTUnwrap(raw["day"] as? String)
            let logs = try events(day, extra: raw["extraEvents"] as? [[String: Any]] ?? [])
            let corrections = (raw["corrections"] as? [[String: Any]] ?? []).compactMap(correction)
            let namedPlaces = places(raw["places"] as? [[String: Any]] ?? [])
            let analysis = analyzeTimeline(logs, adjustments: TimelineAdjustments(corrections: corrections, places: namedPlaces))
            let activities = buildTimelineActivities(logs, analysis: analysis)

            XCTAssertEqual(activities.count, item.activities.count, item.name)
            for (index, (activity, expectedActivity)) in zip(activities, item.activities).enumerated() {
                let label = "\(item.name) activity \(index)"
                XCTAssertEqual(activity.kind == .stay ? "stay" : "movement", expectedActivity.kind, label)
                XCTAssertEqual(milliseconds(activity.startedAt), expectedActivity.startedAt, label)
                XCTAssertEqual(milliseconds(activity.endedAt), expectedActivity.endedAt, label)
                XCTAssertEqual(activity.photos.count, expectedActivity.photoCount, label)
                if activity.kind == .movement {
                    XCTAssertEqual(milliseconds(Date(timeIntervalSince1970: activity.untracked)), expectedActivity.untrackedMs ?? -1, label)
                }
                if activity.kind == .stay {
                    XCTAssertEqual(activity.coordinate?.latitude ?? .nan, try XCTUnwrap(expectedActivity.latitude), accuracy: 1e-5, label)
                    XCTAssertEqual(activity.coordinate?.longitude ?? .nan, try XCTUnwrap(expectedActivity.longitude), accuracy: 1e-5, label)
                    XCTAssertEqual(activity.placeId, expectedActivity.placeId, label)
                    XCTAssertEqual(activity.corrected, expectedActivity.corrected ?? false, label)
                }
            }

            let outliers = findOutlierCandidates(analysis)
            XCTAssertEqual(outliers.count, item.outliers.count, item.name)
            for (outlier, expectedOutlier) in zip(outliers, item.outliers) {
                XCTAssertEqual(milliseconds(outlier.startedAt), expectedOutlier.startedAt, item.name)
                XCTAssertEqual(milliseconds(outlier.endedAt), expectedOutlier.endedAt, item.name)
                XCTAssertEqual(outlier.eventIds, expectedOutlier.eventIds, item.name)
            }
        }
    }

    func testGroupsEverySampleDayIntoTheSameAllTimePlaces() throws {
        let root = try XCTUnwrap(JSONSerialization.jsonObject(with: fixture("corrections.cases.json")) as? [String: Any])
        let allPlaces = try XCTUnwrap(root["allPlaces"] as? [String: Any])
        let days = try XCTUnwrap(allPlaces["days"] as? [String])
        let corrections = (allPlaces["corrections"] as? [[String: Any]] ?? []).compactMap(correction)
        let namedPlaces = places(allPlaces["places"] as? [[String: Any]] ?? [])
        let expected = try JSONDecoder().decode(Expected.self, from: fixture("corrections.expected.json"))

        let stays = try days.flatMap { detectDayStays(try events($0), corrections: corrections) }
        let places = buildAllTimeStayPlaces(stays, namedPlaces: namedPlaces)

        XCTAssertEqual(places.count, expected.allPlaces.count)
        for (place, expectedPlace) in zip(places, expected.allPlaces) {
            XCTAssertEqual(place.placeId, expectedPlace.placeId)
            XCTAssertEqual(place.coordinate.latitude, expectedPlace.latitude, accuracy: 1e-5)
            XCTAssertEqual(place.coordinate.longitude, expectedPlace.longitude, accuracy: 1e-5)
            XCTAssertEqual(place.visits.count, expectedPlace.visitCount)
            XCTAssertEqual(place.dayCount, expectedPlace.dayCount)
            XCTAssertEqual(Int64((place.totalDuration * 1000).rounded()), expectedPlace.totalDurationMs)
        }
    }
}
